select je.* , cc.id as sub_id, jsr.back_number, cc.player_name from jw_eight je
left join jw_sign_record jsr on jsr.id = je.player_id
left join jw_sign_record_sport b on b.sign_record_id = je.player_id
left join jw_sport cc on cc.id = b.sport_id

     and je.player_id = #{playerId}
     and je.player_index = #{playerIndex}
     and je.player_position = #{playerPosition}
     and je.player_pk_group = #{playerPkGroup}
     and je.game_item_id = #{gameItemId}
     and je.group_index = #{groupIndex}

mapper.update:
update jw_eight
player_id = #{playerId}, player_index = #{playerIndex}, player_position = #{playerPosition}, player_pk_group = #{playerPkGroup}, game_item_id = #{gameItemId}, group_index = #{groupIndex},
where id = #{id}

update jw_eight
set player_id = #{playerId}
where game_item_id = #{gameItemId} and player_position = #{playerPosition} and player_index = #{playerIndex}

update jw_eight

    player_id = #{playerId},

where player_position = #{playerPosition} and player_group = #{playerGroup}

UPDATE jw_eight  SET eight_order = null where player_pk_group = '2.0' and player_group = #{playerGroup};
update jw_eight j set j.eight_order = '4'
where j.player_pk_group = '2.0'
and j.player_id not in
 (select jj.player_id from (select jjj.player_id from jw_eight jjj where jjj.player_pk_group = '2' and jjj.player_group = #{playerGroup}) jj)
and j.player_group = #{playerGroup};

UPDATE jw_eight  SET eight_order = null where player_pk_group = '1.1' and player_group = #{playerGroup};
update jw_eight j set j.eight_order = '2'
where j.player_pk_group = '1.1'
and j.player_id not in
(select jj.player_id from (select jjj.player_id from jw_eight jjj where jjj.player_pk_group = '1' and jjj.player_group = #{playerGroup}) jj)
and j.player_group = #{playerGroup};

UPDATE jw_eight  SET eight_order = null where player_pk_group in ('4.1', '4.2', '4.3', '4.4') and player_group = #{playerGroup};
UPDATE jw_eight a, (SELECT @rank := 0) r, (SELECT (@rank := @rank + 1) i, id FROM jw_eight j
WHERE j.player_group = #{playerGroup}
and j.player_pk_group in ('4.1', '4.2', '4.3', '4.4')
and j.player_id not in
(select player_id from jw_eight where player_id is not null and player_id != '' and player_group = #{playerGroup} and player_pk_group in ('2.1', '2.2'))
order by (j.player_index+0) asc) i
SET a.eight_order = i + 4
WHERE a.id = i.id;
